import requests, sys, time, uuid

BASE = '{{TESTVDB_DB_URL}}'

# Test state_residual on /v1/schema/{className}/properties
# Add a property, then verify it exists, then test no residual state

c = 'TestStateResidual_' + uuid.uuid4().hex[:8]

# Delete if exists
requests.delete(f'{BASE}/v1/schema/{c}')

# Create schema
payload = {
    "class": c,
    "vectorizer": "none",
    "vectorIndexConfig": {
        "distance": "cosine",
        "efConstruction": 128,
        "maxConnections": 32
    },
    "replicationConfig": {
        "factor": 1
    },
    "multiTenancyConfig": {
        "enabled": False
    },
    "properties": [
        {
            "name": "text",
            "dataType": ["text"]
        }
    ]
}

r = requests.post(f'{BASE}/v1/schema', json=payload)
print(f'Create schema: {r.status_code}')
if r.status_code != 200:
    print(f'Create failed: {r.text}')
    # Try without some optional fields
    payload2 = {
        "class": c,
        "vectorizer": "none",
        "vectorIndexConfig": {
            "distance": "cosine"
        },
        "properties": [
            {
                "name": "text",
                "dataType": ["text"]
            }
        ]
    }
    r = requests.post(f'{BASE}/v1/schema', json=payload2)
    print(f'Create schema (retry): {r.status_code} {r.text}')
    if r.status_code != 200:
        sys.exit(0)

time.sleep(0.5)

# Add a new property via /v1/schema/{className}/properties
prop_payload = {
    "className": c,
    "name": "extra_field",
    "dataType": ["text"]
}
r2 = requests.post(f'{BASE}/v1/schema/{c}/properties', json=prop_payload)
print(f'Add property: {r2.status_code} {r2.text}')

if r2.status_code == 200:
    # Verify property exists
    r3 = requests.get(f'{BASE}/v1/schema/{c}')
    if r3.status_code == 200:
        props = r3.json().get('properties', [])
        prop_names = [p.get('name') for p in props]
        print(f'Properties after add: {prop_names}')
        if 'extra_field' in prop_names:
            print
